)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">4</text><path class="wheel-step__line" d="M601 90v116"></path></g><g class="wheel-step" transform="rotate(240 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">5</text><path class="wheel-step__line" d="M601 90v116"></path></g><g class="wheel-step" transform="rotate(300 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">6</text><path class="wheel-step__line" d="M601 90v116"></path></g><!--]--></svg><!--[--><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Personalized Care & Consultation </h3><p class="u-text-body-medium wheel-block-wheel__item-description">Dr. Kriti Shrivastava spends time understanding your dental concerns, lifestyle, and goals before creating a fully personalized care plan tailored for your oral health.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Predictable Results & Clear Diagnosis</h3><p class="u-text-body-medium wheel-block-wheel__item-description">Advanced digital X-rays and oral examination enable precise diagnosis and predictable clinical outcomes — so you always know what to expect before treatment begins.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Comfort & Safety in Every Visit</h3><p class="u-text-body-medium wheel-block-wheel__item-description">We use modern anaesthesia and gentle techniques to ensure your treatment is virtually pain-free. No discomfort, no anxiety — just safe, careful dental care.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Relaxed & Calm Environment</h3><p class="u-text-body-medium wheel-block-wheel__item-description">Our clinic is designed to be calm, clean, and welcoming — from the moment you walk in, you will feel at ease in a safe and hygienic environment.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Everything Under One Roof</h3><p class="u-text-body-medium wheel-block-wheel__item-description">From general check-ups and fillings to dental implants, braces, root canals, and full-mouth rehabilitation — all 13 dental treatments are available under one roof.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Complete Hygiene & Patient Privacy</h3><p class="u-text-body-medium wheel-block-wheel__item-description">Every instrument is thoroughly sterilized and clinic hygiene protocols strictly followed. Your safety is our top priority at every single visit.</p></div><!--]--></div><!--]--></div></div></div></div><div class="wheel-block__triggers"><!--[--><div data-nr="1" class="wheel-block__trigger"></div><div data-nr="2" class="wheel-block__trigger"></div><div data-nr="3" class="wheel-block__trigger"></div><div data-nr="4" class="wheel-block__trigger"></div><div data-nr="5" class="wheel-block__trigger"></div><div data-nr="6" class="wheel-block__trigger"></div><!--]--></div></div></div><!--]--></div><div class="overlay-section"><!--[--><div class="reveal-block about-apply"><div class="reveal-block__content"><div class="reveal-block__header u-bg-secondary"><div class="container container--size-default"><!--[--><p class="reveal-block__title u-text-headings-large"><span class="word" aria-hidden="true" style="display: inline-block;">This</span> <span class="word" aria-hidden="true" style="display: inline-block;">is</span> <span class="word" aria-hidden="true" style="display: inline-block;">us</span> <span class="word" aria-hidden="true" style="display: inline-block;">—</span> <span class="word u-text-wine" aria-hidden="true" style="display: inline-block;">Shrivastava</span> <span class="word u-text-wine" aria-hidden="true" style="display: inline-block;">Dental</span> <span class="word u-text-wine" aria-hidden="true" style="display: inline-block;">Clinic.</span><span class="sr-only" style="position: absolute; width: 1px; height: 1px; padding: 0px; margin: -1px; overflow: hidden; clip: rect(0px, 0px, 0px, 0px); white-space: nowrap; border: 0px;">This is us Shrivastava Dental Clinic.</span></p><!--]--></div></div><div class="u-bg-primary reveal-block__body" style=""><div class="reveal-block__bg"><canvas class="lava-bg-illustration reveal-block__bg-illustration" width="1920" height="1230"></canvas><div class="container container--size-default"><!--[--><p class="reveal-block__title reveal-block__title--bg u-text-headings-large"><span class="u-text-white">This is us -</span> <span class="u-text-gold">Shrivastava Dental Clinic.</span></p><!--]--></div></div><div class="container container--size-default"><!--[--><div class="reveal-block__main-wrap"><div class="reveal-block__main"><!--[--><div class="about-apply-grid"><div class="about-apply-grid__item about-apply-box u-bg-secondary"><div class="about-apply-box__aside"><div class="video-dialog video-dialog--type-cover about-apply-box__preview"><video class="video-dialog__preview" width="300" height="534" muted="" loop="" playsinline="" src="/cms/api/media/file/shrivastava%20video.mp4?v=3" autoplay=""></video><button aria-label="Play video" class="video-dialog__button"><div class="icon-button icon-button--type-primary icon-button--size-medium video-dialog__play-button"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="54" height="54" viewBox="0 0 54 54"><path fill="currentColor" d="M22.031 19.687a1 1 0 0 1 1.515-.858l12.188 7.313a1 1 0 0 1 0 1.715L23.546 35.17a1 1 0 0 1-1.515-.857V19.687Z"></path></svg><!--]--></div></div></button><!--teleport start--><!--teleport end--></div></div><div class="about-apply-box__body"><p class="u-text-headings-small">Book your visit and take the first step towards your healthiest, most confident smile!</p><a class="button button--type-secondary button--icon-end about-apply-box__cta-button" href="tel:7796376170" target="_blank"><div class="button__text u-text-body-button"><!--[-->Book an Appointment<!--]--></div><!----></a></div></div></div><!--]--></div></div><!--]--></div></div></div><div class="reveal-block__timeline"><div class="reveal-block__timeline-item reveal-block__timeline-item--intro"></div><div class="reveal-block__timeline-item reveal-block__timeline-item--main"></div></div></div><!--]--></div></section>
