lt"><!--[--><div class="services-list-item-grid"><!--[--><div class="services-list-item-grid__item service-list-item" style="--delay:0s;"><div class="service-list-item__nr u-text-body-large">06</div><h3 class="service-list-item__title u-text-headings-small">Pain-free Anesthesia</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#1A1A1A" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><div class="services-list-item-grid__item service-list-item" style="--delay:0.3s;"><div class="service-list-item__nr u-text-body-large">07</div><h3 class="service-list-item__title u-text-headings-small">Dental Therapy</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#1A1A1A" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><div class="services-list-item-grid__item service-list-item" style="--delay:0.6s;"><div class="service-list-item__nr u-text-body-large">08</div><h3 class="service-list-item__title u-text-headings-small">Endodontics</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#1A1A1A" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><div class="services-list-item-grid__item service-list-item" style="--delay:0.8999999999999999s;"><div class="service-list-item__nr u-text-body-large">09</div><h3 class="service-list-item__title u-text-headings-small">Oral and Maxillofacial Surgery</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#1A1A1A" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><div class="services-list-item-grid__item service-list-item" style="--delay:1.2s;"><div class="service-list-item__nr u-text-body-large">10</div><h3 class="service-list-item__title u-text-headings-small">Aligners</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#1A1A1A" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><!--]--></div><!--]--></div></div></div></div></section>
<section id="faq" style="view-timeline:--tl-section-faq;"><div class="faq u-bg-secondary"><div class="container container--size-default"><!--[--><div class="faq__header"><h2 class="u-text-headings-large">Frequently Asked <span class="u-text-wine">Questions</span></h2></div><div class="faq__body"><div class="faq-categories"><!--[--><details class="details details--size-large faq-category" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-headings-small details__title">Treatments &amp; Procedures</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="faq-items"><!--[--><details class="details details--size-small faq-item" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">How long do dental implants last?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>With proper oral hygiene, regular dental check-ups, and good overall health, dental implants can last 7–10 years or even longer. Their lifespan depends on individual dental health and maintenance.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">How can I get a brighter smile?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Professional teeth cleaning, whitening, and cosmetic dental treatments can help improve your smile. Our dentist can recommend the most suitable option based on your dental condition.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.2s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Are teeth whitening procedures safe?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Yes, professional teeth whitening is generally safe when performed under a dentist's supervision. A dental assessment helps ensure the treatment is suitable and minimizes potential sensitivity.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.3s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Are dental veneers permanent?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Dental veneers are long-lasting but not permanent. Depending on their material and maintenance, they may need replacement over time. Some veneers require irreversible enamel removal.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.4s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Do you provide digital dental X-rays?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Yes, we provide digital IOPA X-rays at our clinic. For advanced imaging such as OPG and CBCT scans, we refer patients to specialized diagnostic centres.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.5s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Do you have specialists for different dental treatments?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Yes, we provide specialized dental care, particularly in pediatric dentistry and orthodontics. Based on your needs, we guide you to the appropriate specialist.</p></div></div><!--]--></div></details><!--]--></div><!--]--></div></details><details class="details details--size-large faq-category" style="--delay:0.2s;"><summary class="details__header" style=""><div class="u-text-headings-small details__title">Dental Health &amp; Prevention</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="faq-items"><!--[--><details class="details details--size-small faq-item" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">How often should I visit a dentist?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>It is generally recommended to visit your dentist every six months for routine check-ups and professional cleaning. More frequent visits may be required depending on your dental health.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Can dental problems affect my overall health?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Yes, untreated dental problems and gum infections can affect your overall health and may be linked to other health conditions. Regular check-ups and good oral hygiene help prevent complications.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.2s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">What causes bad breath even after brushing?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Persistent bad breath can result from gum disease, tooth decay, food habits, medication, or bacterial buildup on the tongue. A dental check-up can help identify the underlying cause.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.3s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">How can I stop my child from thumb sucking?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Encourage your child gently using positive reinforcement rather than punishment. If the habit continues as they grow, consult a pediatric dentist to prevent possible effects on tooth alignment and jaw development.</p></div></div><!--]--></div></details><!--]--></div><!--]--></div></details><details class="details details--size-large faq-category" style="--delay:0.3s;"><summary class="details__header" style=""><div class="u-text-headings-small details__title">Appointments &amp; Patient Services</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="faq-items"><!--[--><details class="details details--size-small faq-item" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Do you offer free dental consultations?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>No, we do not offer free consultations. Our consultations include a professional dental evaluation and personalized treatment recommendations based on your needs.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Do you offer appointment booking through WhatsApp?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Yes, you can contact us through WhatsApp for appointment enquiries and scheduling. Visit our website and use the WhatsApp contact option for further assistance.</p></div></div><!--]--></div></details><!--]--></div><!--]--></div></details><details class="details details--size-large faq-category" style="--delay:0.4s;"><summary class="details__header" style=""><div class="u-text-headings-small details__title">Insurance &amp; Payment</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="faq-items"><!--[--><details class="details details--size-small faq-item" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Does health insurance cover dental procedures?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Some health insurance policies cover specific dental procedures, depending on the provider and policy terms. We recommend checking with your insurance provider to confirm your coverage before treatment.</p></div></div><!--]--></div></details><!--]--></div><!--]--></div></details><!--]--></div></section>
